bool Sexy::ExtractResourcesByName(ResourceManager* theManager, const char* theName)
{
	if (strcmp(theName, "3dImages") == 0)
		return Extract3dImagesResources(theManager);
	if (strcmp(theName, "Init") == 0)
		return ExtractInitResources(theManager);
	if (strcmp(theName, "InitialMainMenu") == 0)
		return ExtractInitialMainMenuResources(theManager);
	if (strcmp(theName, "LoadScreen") == 0)
		return ExtractLoadScreenResources(theManager);
	if (strcmp(theName, "LoadingThread") == 0)
		return ExtractLoadingThreadResources(theManager);
	if (strcmp(theName, "NonResize") == 0)
		return ExtractNonResizeResources(theManager);
	if (strcmp(theName, "Sounds") == 0)
		return ExtractSoundsResources(theManager);
	return false;
}
